#include <bits/stdc++.h>
using namespace std;

int main() {
	int n, m, k, l;
	int u, v, sz;
	long long c;
	cin >> n >> m >> k >> l;

	vector<int>a(n);
	vector<vector<pair<int, long long> > >e(n);
	vector<int>cnt(n, 0);
	vector<long long>d(n, -1);
	vector<int>country(n);
	vector<long long>d2(n, -1);
	priority_queue<tuple<long long, int, int> >pq;

	for (int i = 0; i < n; i++)cin >> a[i];
	for (int i = 0; i < l; i++) {
		cin >> u;
		pq.push({ 0LL,u - 1,a[u - 1] });
	}
	for (int i = 0; i < m; i++) {
		cin >> u >> v >> c;
		e[u - 1].push_back({ v - 1,c });
		e[v - 1].push_back({ u - 1, c });
	}
	while (!pq.empty()) {
		auto[z, x, y] = pq.top();
		pq.pop();
		if (cnt[x] == 0) {
			d[x] = -z;
			country[x] = y;
		}
		else if ((cnt[x] == 1) && (y != country[x])) {
			d2[x] = -z;
		}
		else continue;
		cnt[x]++;
		sz = e[x].size();
		for (int i = 0; i < sz; i++)pq.push({ z - e[x][i].second,e[x][i].first,y });
	}
	for (int i = 0; i < n; i++) {
		if (a[i] != country[i])cout << d[i];
		else cout << d2[i];
		if (i < (n - 1))cout << " ";
		else cout << endl;
	}
	return 0;
}
